//! End-to-end tests of the `recast-radar` binary on real files.
//!
//! Expected values come from the Py-ART and xradar goldens in
//! `testdata/conformance/fm301` (generated by `tools/fm301_golden.py`), and
//! from the testdata manifest descriptions, whose counts were taken with
//! Py-ART and MetPy.

// A failed expectation in a test helper is a test failure.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::ffi::OsStr;
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::{Command, Output, Stdio};

use serde_json::Value;

fn run<I, S>(args: I) -> Output
where
    I: IntoIterator<Item = S>,
    S: AsRef<OsStr>,
{
    Command::new(env!("CARGO_BIN_EXE_recast-radar"))
        .args(args)
        .output()
        .expect("run recast-radar")
}

fn fixture(id: &str) -> PathBuf {
    recast_radar_testdata::path(id).unwrap_or_else(|err| panic!("{err}"))
}

fn stdout(output: &Output) -> String {
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn stderr(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

fn json(output: &Output) -> Value {
    assert!(output.status.success(), "{}", stderr(output));
    serde_json::from_slice(&output.stdout).expect("JSON output")
}

/// An empty directory for one test's output.
fn scratch(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("recast-radar-cli-{name}-{}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create scratch directory");
    dir
}

fn golden(kind: &str, id: &str) -> Value {
    let path = recast_radar_testdata::workspace_root()
        .join("testdata/conformance/fm301")
        .join(kind)
        .join(format!("{id}.json"));
    serde_json::from_slice(&fs::read(&path).expect("read golden")).expect("parse golden")
}

const ESPDG: &str = "odim-espdg-20260707-1927-pvol-dbzh-vradh";

#[test]
fn help_names_every_command() {
    let output = run(["--help"]);
    assert!(output.status.success());
    let text = stdout(&output);
    for command in [
        "info", "dump", "render", "fetch", "validate", "bench", "convert", "publish", "serve",
    ] {
        assert!(
            text.contains(&format!("  {command}  ")),
            "{command}: {text}"
        );
    }
    let version = stdout(&run(["--version"]));
    assert_eq!(
        version.trim(),
        format!("recast-radar {}", env!("CARGO_PKG_VERSION"))
    );
}

#[test]
fn invalid_arguments_exit_with_status_2() {
    let output = run(["info"]);
    assert_eq!(output.status.code(), Some(2));
    let output = run([
        OsStr::new("dump"),
        OsStr::new("--sweep"),
        OsStr::new("99"),
        fixture(ESPDG).as_os_str(),
    ]);
    assert_eq!(output.status.code(), Some(2), "{}", stderr(&output));
    assert!(
        stderr(&output).contains("2 sweep(s)"),
        "{}",
        stderr(&output)
    );
}

/// Manifest: sweep 1 REF/ZDR/PHI/RHO/CFP and sweep 2 REF/VEL/SW, 480 of 720
/// radials each, VCP 212, Build 22.0.
#[test]
fn info_summarizes_a_trimmed_level2_volume() {
    let path = fixture("l2-ktlx-20240315-000217-trim");
    let output = run([path.as_os_str()]);
    // `info` is required: a bare file is not a command.
    assert_eq!(output.status.code(), Some(2));

    let output = run([OsStr::new("info"), path.as_os_str()]);
    assert!(output.status.success(), "{}", stderr(&output));
    let text = stdout(&output);
    for expected in [
        "NEXRAD Level II",
        "KTLX",
        "VCP 212",
        "2 sweeps, 960 rays",
        "DBZH ZDR PHIDP RHOHV CCORH",
        "DBZH VRADH WRADH",
    ] {
        assert!(text.contains(expected), "{expected}: {text}");
    }

    let report = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        path.as_os_str(),
    ]));
    let volume = &report["volumes"][0];
    assert_eq!(volume["site"], "KTLX");
    assert_eq!(volume["vcp"], 212);
    assert_eq!(volume["sweep_count"], 2);
    for sweep in volume["sweeps"].as_array().expect("sweeps") {
        assert_eq!(sweep["rays"], 480);
        assert!((sweep["fixed_angle_deg"].as_f64().unwrap_or(0.0) - 0.48).abs() < 0.01);
    }
}

/// Py-ART `aux_io.read_odim_h5`: 2 sweeps of 360 rays and 299 gates.
#[test]
fn info_json_agrees_with_pyart_on_an_odim_volume() {
    let pyart = golden("pyart", ESPDG);
    let report = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        fixture(ESPDG).as_os_str(),
    ]));
    assert_eq!(report["format"], "ODIM_H5");
    let volume = &report["volumes"][0];
    assert_eq!(volume["sweep_count"], pyart["radar"]["nsweeps"]);
    let sweeps = volume["sweeps"].as_array().expect("sweeps");
    for (sweep, reference) in sweeps
        .iter()
        .zip(pyart["radar"]["sweeps"].as_array().expect("sweeps"))
    {
        assert_eq!(sweep["rays"], reference["rays"]);
        assert_eq!(sweep["gates"], pyart["radar"]["ngates"]);
    }
}

