/// Manifest: TAKA, 26 sweeps of 512 radials.
#[test]
fn a_jma_station_is_chosen_with_station() {
    let path = fixture("jma-n5-20191012-090000-rs47773");
    let report = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        OsStr::new("--station"),
        OsStr::new("TAKA"),
        path.as_os_str(),
    ]));
    let volume = &report["volumes"][0];
    assert_eq!(volume["site"], "TAKA");
    assert_eq!(volume["sweep_count"], 26);
    for sweep in volume["sweeps"].as_array().expect("sweeps") {
        assert_eq!(sweep["rays"], 512);
    }
    let output = run([
        OsStr::new("info"),
        OsStr::new("--station"),
        OsStr::new("NOPE"),
        path.as_os_str(),
    ]);
    assert_eq!(output.status.code(), Some(1));
}

/// EUMETNET ORD serves a BEJAB scan as one file per moment; the file names
/// list the elevations (0.5 to 25 deg), so the merged volume has those 9
/// sweeps, each with both moments.
#[test]
fn info_merges_parts_of_one_scan() {
    let dbzh = fixture("odim-bejab-20260612-1450-dbzh");
    let vrad = fixture("odim-bejab-20260612-1450-vrad");
    let report = json(&run([
        OsStr::new("info"),
        OsStr::new("--merge"),
        OsStr::new("--json"),
        dbzh.as_os_str(),
        vrad.as_os_str(),
    ]));
    let volume = &report["volumes"][0];
    assert_eq!(volume["site"], "BEJAB");
    let sweeps = volume["sweeps"].as_array().expect("sweeps");
    let angles: Vec<f64> = sweeps
        .iter()
        .map(|sweep| (sweep["fixed_angle_deg"].as_f64().unwrap_or(f64::NAN) * 10.0).round() / 10.0)
        .collect();
    assert_eq!(angles, [0.5, 1.2, 2.1, 3.4, 4.8, 6.5, 9.0, 13.0, 25.0]);
    for sweep in sweeps {
        assert_eq!(sweep["fields"], serde_json::json!(["DBZH", "VRAD"]));
    }
    // Without --merge, several files are summarized one by one.
    let reports = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        dbzh.as_os_str(),
        vrad.as_os_str(),
    ]));
    assert_eq!(reports.as_array().map(Vec::len), Some(2));
}

/// Py-ART masks ODIM `nodata` and `undetect`; the unmasked gates are the
/// `values` of `dump`, with the same range.
#[test]
fn dump_field_statistics_agree_with_pyart() {
    let pyart = golden("pyart", ESPDG);
    let report = json(&run([
        OsStr::new("dump"),
        OsStr::new("--json"),
        OsStr::new("--field"),
        OsStr::new("dbzh"),
        fixture(ESPDG).as_os_str(),
    ]));
    let sweeps = report["volumes"][0]["sweeps"].as_array().expect("sweeps");
    let reference = pyart["fields"]["reflectivity_horizontal"]["per_sweep"]
        .as_array()
        .expect("per-sweep statistics");
    assert_eq!(sweeps.len(), reference.len());
    for (sweep, expected) in sweeps.iter().zip(reference) {
        let fields = sweep["fields"].as_array().expect("fields");
        assert_eq!(fields.len(), 1, "--field keeps only DBZH");
        let stats = &fields[0]["stats"];
        assert_eq!(stats["values"], expected["count_unmasked"]);
        assert_eq!(stats["min"].as_f64(), expected["min"].as_f64());
        assert_eq!(stats["max"].as_f64(), expected["max"].as_f64());
        let mean = stats["mean"].as_f64().expect("mean");
        let expected_mean = expected["mean"].as_f64().expect("mean");
        assert!(
            (mean - expected_mean).abs() < 1e-6,
            "{mean} vs {expected_mean}"
        );
    }
}

#[test]
fn dump_data_rows_have_the_field_shape() {
    let report = json(&run([
        OsStr::new("dump"),
        OsStr::new("--json"),
        OsStr::new("--sweep"),
        OsStr::new("1"),
        OsStr::new("--field"),
        OsStr::new("VRADH"),
        OsStr::new("--data"),
        fixture(ESPDG).as_os_str(),
    ]));
    let sweeps = report["volumes"][0]["sweeps"].as_array().expect("sweeps");
    assert_eq!(sweeps.len(), 1);
    assert_eq!(sweeps[0]["index"], 1);
    let field = &sweeps[0]["fields"][0];
    let rows = field["data"].as_array().expect("data rows");
    assert_eq!(rows.len(), 360);
    assert!(
        rows.iter()
            .all(|row| row.as_array().map(Vec::len) == Some(299))
    );
    let valid = rows
        .iter()
        .flat_map(|row| row.as_array().into_iter().flatten())
        .filter(|value| value.is_number())
        .count();
    assert_eq!(valid as u64, field["stats"]["values"].as_u64().unwrap_or(0));

    // The text form carries the same metadata.
    let output = run([
        OsStr::new("dump"),
        OsStr::new("--sweep"),
        OsStr::new("0"),
        fixture(ESPDG).as_os_str(),
    ]);
    assert!(output.status.success());
    let text = stdout(&output);
    assert!(text.contains("field DBZH:"), "{text}");
    assert!(text.contains("instrument_name: ESPDG"), "{text}");
}

/// Level III Storm Tracking Information (product 58): the headers are JSON
/// objects, and every storm-id packet is there with MetPy's position (the
/// tracking golden, `tools/track_golden.py`: MetPy `Level3File` x/y in km).
#[test]
fn dump_level3_gives_packets_and_pages_as_json() {
    let report = json(&run([
        OsStr::new("dump"),
        OsStr::new("--json"),
        fixture("l3-kdvn-20200810-1804-nst").as_os_str(),
    ]));
    let level3 = &report["level3"];
    assert_eq!(level3["message_header"]["code"], 58);
    assert_eq!(level3["description"]["product_code"], 58);
    assert_eq!(level3["description"]["vcp"], 212);
    assert_eq!(level3["text_header"]["awips_id"], "NSTDVN");

    let mut positions = std::collections::HashMap::new();
    for layer in level3["symbology"]["layers"].as_array().expect("layers") {
        for packet in layer.as_array().expect("packets") {
            assert!(packet["code"].as_str().is_some_and(|c| c.starts_with("0x")));
            for storm in packet["packet"]["StormIds"]
                .as_array()
                .into_iter()
                .flatten()
            {
                let at = |key: &str| storm[key].as_f64().expect("position") / 4.0;
                positions.insert(
                    storm["id"].as_str().expect("id").to_owned(),
                    (at("i"), at("j")),
                );
            }
        }
    }
    let golden: Value = serde_json::from_slice(
        &fs::read(
            recast_radar_testdata::workspace_root().join("testdata/golden/track/tracking.json"),
        )
        .expect("read golden"),
    )
    .expect("parse golden");
    let volume = golden["kdvn"]["volumes"]
        .as_array()
        .expect("volumes")
        .iter()
        .find(|v| v["sti"] == "l3-kdvn-20200810-1804-nst")
        .expect("golden volume");
    let storms = volume["storms"].as_array().expect("storms");
    assert_eq!(positions.len(), storms.len());
    for storm in storms {
        let id = storm["id"].as_str().expect("id");
        let expected = (
            storm["east_km"].as_f64().expect("east"),
            storm["north_km"].as_f64().expect("north"),
        );
        assert_eq!(positions.get(id), Some(&expected), "storm {id}");
    }

    // The graphic pages' text packets and the tabular pages.
    let pages = level3["graphic"]["pages"]
        .as_array()
        .expect("graphic pages");
    assert_eq!(pages.len(), 6);
    let first_line = pages[0]["packets"][0]["packet"]["text"]
        .as_str()
        .expect("text");
    assert!(first_line.contains("STORM ID"), "{first_line}");
    let tabular = level3["tabular"]["pages"][0][1]
        .as_str()
        .expect("tabular line");
    assert!(tabular.contains("NUMBER OF STORM CELLS  45"), "{tabular}");
}

