/// xradar `open_odim_datatree` (first_dim="auto"): the sweep groups and
/// their dimensions.
#[test]
fn dump_fm301_has_the_xradar_groups() {
    let xradar = golden("xradar", ESPDG);
    let tree = json(&run([
        OsStr::new("dump"),
        OsStr::new("--fm301"),
        OsStr::new("--json"),
        fixture(ESPDG).as_os_str(),
    ]));
    fn collect(group: &Value, parent: &str, out: &mut Vec<(String, Value)>) {
        let name = group["name"].as_str().unwrap_or("?");
        let path = if name == "/" {
            "/".to_owned()
        } else {
            format!("{}/{name}", parent.trim_end_matches('/'))
        };
        out.push((path.clone(), group["dimensions"].clone()));
        for child in group["groups"].as_array().into_iter().flatten() {
            collect(child, &path, out);
        }
    }
    let mut ours = Vec::new();
    collect(&tree, "", &mut ours);
    let theirs: Vec<(String, Value)> = xradar["views"]["auto"]["groups"]
        .as_array()
        .expect("groups")
        .iter()
        .map(|group| {
            (
                group["path"].as_str().unwrap_or("").to_owned(),
                group["dims"].clone(),
            )
        })
        .collect();
    // FM301 gives every sweep the `frequency` dimension, which xradar 0.12
    // leaves out for ODIM (a documented divergence of the core conformance
    // test, design note section 1).
    let sweeps = |groups: &[(String, Value)]| -> Vec<(String, Value)> {
        groups
            .iter()
            .filter(|(path, _)| path.starts_with("/sweep_"))
            .map(|(path, dims)| {
                let mut dims = dims.clone();
                if let Some(map) = dims.as_object_mut() {
                    map.remove("frequency");
                }
                (path.clone(), dims)
            })
            .collect()
    };
    assert_eq!(sweeps(&ours), sweeps(&theirs));
    assert_eq!(sweeps(&ours).len(), 2);
    assert!(ours.iter().any(|(path, _)| path == "/radar_parameters"));
}

fn png_size(path: &Path) -> (u32, u32) {
    let image = png_rgba(path);
    (image.width(), image.height())
}

fn png_rgba(path: &Path) -> image::RgbaImage {
    let bytes = fs::read(path).expect("read PNG");
    image::load_from_memory(&bytes)
        .expect("decode PNG")
        .to_rgba8()
}

/// The opaque pixels of a plan-view render: there are some, every pixel is
/// either transparent or opaque, the corners are transparent, and none lies
/// beyond `range_fraction` of the half-width from the centre (where the far
/// edge of the last gate is drawn).
fn check_plan_view(image: &image::RgbaImage, range_fraction: f64) -> Vec<[u8; 3]> {
    let (width, height) = image.dimensions();
    let centre = (f64::from(width) - 1.0) / 2.0;
    let limit = range_fraction * f64::from(width) / 2.0 + 1.5;
    let mut colours = Vec::new();
    for (x, y, pixel) in image.enumerate_pixels() {
        let [r, g, b, a] = pixel.0;
        assert!(a == 0 || a == 255, "alpha {a} at ({x}, {y})");
        if a == 255 {
            let distance = (f64::from(x) - centre).hypot(f64::from(y) - centre);
            assert!(
                distance <= limit,
                "pixel ({x}, {y}) at {distance:.1} px, limit {limit:.1}"
            );
            colours.push([r, g, b]);
        }
    }
    for (x, y) in [
        (0, 0),
        (width - 1, 0),
        (0, height - 1),
        (width - 1, height - 1),
    ] {
        assert_eq!(image.get_pixel(x, y).0[3], 0, "corner ({x}, {y})");
    }
    assert!(!colours.is_empty(), "no opaque pixel");
    colours
}

/// Whether `colour` lies on the piecewise-linear gradient through `stops`
/// (within 2 levels per channel), as a GR palette of single colours draws.
fn on_gradient(colour: [u8; 3], stops: &[[u8; 3]]) -> bool {
    stops.windows(2).any(|pair| {
        let (a, b) = (pair[0].map(f64::from), pair[1].map(f64::from));
        let c = colour.map(f64::from);
        let ab: Vec<f64> = (0..3).map(|i| b[i] - a[i]).collect();
        let length = ab.iter().map(|d| d * d).sum::<f64>();
        let t = if length == 0.0 {
            0.0
        } else {
            ((0..3).map(|i| (c[i] - a[i]) * ab[i]).sum::<f64>() / length).clamp(0.0, 1.0)
        };
        (0..3).all(|i| (a[i] + t * ab[i] - c[i]).abs() <= 2.0)
    })
}

#[test]
fn render_writes_pngs() {
    let dir = scratch("render");
    let level2 = fixture("l2-ktlx-20240315-000217-trim");
    let png = dir.join("ref.png");
    let output = run([
        OsStr::new("render"),
        level2.as_os_str(),
        OsStr::new("--size"),
        OsStr::new("256"),
        OsStr::new("-o"),
        png.as_os_str(),
    ]);
    assert!(output.status.success(), "{}", stderr(&output));
    assert_eq!(png_size(&png), (256, 256));
    let reflectivity = png_rgba(&png);
    check_plan_view(&reflectivity, 0.94);

    let output = run([
        OsStr::new("render"),
        level2.as_os_str(),
        OsStr::new("--field"),
        OsStr::new("velocity"),
        OsStr::new("--dealias"),
        OsStr::new("--all-sweeps"),
        OsStr::new("--size"),
        OsStr::new("128"),
        OsStr::new("-o"),
        dir.join("vel").as_os_str(),
    ]);
    assert!(output.status.success(), "{}", stderr(&output));
    let written: Vec<_> = fs::read_dir(dir.join("vel"))
        .expect("list")
        .map(|entry| entry.expect("entry").path())
        .collect();
    assert_eq!(written.len(), 1, "only sweep 1 has velocity");
    let velocity = png_rgba(&written[0]);
    check_plan_view(&velocity, 0.94);
    assert!(stdout(&output).contains("VRADDH"), "{}", stdout(&output));

    // A Level III raster product (NCZ, packet 0xBA07) and a GR palette.
    let palette = dir.join("ref.pal");
    fs::write(
        &palette,
        "Product: BR\nUnits: dBZ\nColor: 5 4 233 231\nColor: 30 0 200 0\nColor: 50 255 0 0\nColor: 75 255 255 255\n",
    )
    .expect("write palette");
    let raster = dir.join("ncz.png");
    let output = run([
        OsStr::new("render"),
        fixture("l3-fws-ncz-19950517-2304").as_os_str(),
        OsStr::new("--palette"),
        palette.as_os_str(),
        OsStr::new("-o"),
        raster.as_os_str(),
    ]);
    assert!(output.status.success(), "{}", stderr(&output));
    assert_eq!(png_size(&raster), (1024, 1024));
    let stops = [[4, 233, 231], [0, 200, 0], [255, 0, 0], [255, 255, 255]];
    let raster = png_rgba(&raster);
    let opaque: Vec<[u8; 3]> = raster
        .pixels()
        .filter(|pixel| pixel.0[3] == 255)
        .map(|pixel| [pixel.0[0], pixel.0[1], pixel.0[2]])
        .collect();
    assert!(!opaque.is_empty());
    assert!(opaque.iter().all(|colour| on_gradient(*colour, &stops)));

    let polar = dir.join("pal.png");
    let output = run([
        OsStr::new("render"),
        level2.as_os_str(),
        OsStr::new("--palette"),
        palette.as_os_str(),
        OsStr::new("--size"),
        OsStr::new("200"),
        OsStr::new("-o"),
        polar.as_os_str(),
    ]);
    assert!(output.status.success(), "{}", stderr(&output));
    assert_eq!(png_size(&polar), (200, 200));
    let colours = check_plan_view(&png_rgba(&polar), 0.94);
    assert!(
        colours.iter().all(|colour| on_gradient(*colour, &stops)),
        "a colour off the palette"
    );
    // The palette changed the colours: some are in no pixel of the render
    // with the default table.
    assert!(
        colours
            .iter()
            .any(|c| !reflectivity.pixels().any(|p| p.0[..3] == c[..]))
    );
    fs::remove_dir_all(&dir).expect("clean up");
}

