#[test]
fn convert_writes_every_format_and_publish_a_polling_directory() {
    let dir = scratch("convert");
    let espdg = fixture(ESPDG);
    let source = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        fixture(ESPDG).as_os_str(),
    ]));
    let source = &source["volumes"][0];
    let rays: Vec<&Value> = source["sweeps"]
        .as_array()
        .expect("sweeps")
        .iter()
        .map(|sweep| &sweep["rays"])
        .collect();

    // Each writer's file reads back with the source's sweeps and rays.
    for (format, name, read_as) in [
        ("level2", "out.ar2v", "NEXRAD Level II"),
        ("cfradial1", "out.cf1.nc", "CfRadial"),
        ("odim", "out.h5", "ODIM_H5"),
        ("fm301", "out.fm301.nc", "CfRadial"),
    ] {
        let out = dir.join(name);
        let mut args = vec![
            OsStr::new("convert"),
            espdg.as_os_str(),
            OsStr::new("--to"),
            OsStr::new(format),
            OsStr::new("-o"),
            out.as_os_str(),
        ];
        if format == "level2" {
            args.extend([OsStr::new("--site"), OsStr::new("SPDG")]);
        }
        let output = run(&args);
        assert!(output.status.success(), "{format}: {}", stderr(&output));
        let report = json(&run([
            OsStr::new("info"),
            OsStr::new("--json"),
            out.as_os_str(),
        ]));
        assert!(
            report["format"]
                .as_str()
                .is_some_and(|text| text.starts_with(read_as)),
            "{format}: {report}"
        );
        let volume = &report["volumes"][0];
        assert_eq!(volume["sweep_count"], source["sweep_count"], "{format}");
        let read_rays: Vec<&Value> = volume["sweeps"]
            .as_array()
            .expect("sweeps")
            .iter()
            .map(|sweep| &sweep["rays"])
            .collect();
        assert_eq!(read_rays, rays, "{format}");
        if format == "level2" {
            assert_eq!(volume["site"], "SPDG");
        }
    }

    // Real-time chunks: the S, I and E files of one volume, which
    // concatenated are an Archive II file.
    let chunks = dir.join("chunks");
    let output = run([
        OsStr::new("convert"),
        fixture(ESPDG).as_os_str(),
        OsStr::new("--to"),
        OsStr::new("level2"),
        OsStr::new("--chunks"),
        OsStr::new("--site"),
        OsStr::new("SPDG"),
        OsStr::new("-o"),
        chunks.as_os_str(),
    ]);
    assert!(output.status.success(), "{}", stderr(&output));
    let mut files: Vec<PathBuf> = walk(&chunks);
    files.sort();
    assert!(files.len() >= 2, "{files:?}");
    let names: Vec<String> = files
        .iter()
        .filter_map(|path| path.file_name())
        .map(|name| name.to_string_lossy().into_owned())
        .collect();
    assert!(
        names.first().is_some_and(|name| name.ends_with("-001-S")),
        "{names:?}"
    );
    assert!(
        names.last().is_some_and(|name| name.ends_with("-E")),
        "{names:?}"
    );
    let mut archive = Vec::new();
    for file in &files {
        archive.extend(fs::read(file).expect("chunk"));
    }
    let joined = dir.join("joined.ar2v");
    fs::write(&joined, archive).expect("write joined chunks");
    let report = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        joined.as_os_str(),
    ]));
    assert_eq!(report["volumes"][0]["sweep_count"], source["sweep_count"]);

    // publish: a polling directory in the GRLevelX layout.
    let root = dir.join("polling");
    for keep in ["2", "1"] {
        let output = run([
            OsStr::new("publish"),
            fixture(ESPDG).as_os_str(),
            OsStr::new("--dir"),
            root.as_os_str(),
            OsStr::new("--site"),
            OsStr::new("SPDG"),
            OsStr::new("--keep"),
            OsStr::new(keep),
        ]);
        assert!(output.status.success(), "{}", stderr(&output));
    }
    for file in ["config.cfg", "grlevel2.cfg"] {
        let text = fs::read_to_string(root.join(file)).expect("site list");
        assert_eq!(text, "Site: SPDG\r\n", "{file}");
    }
    let listing = fs::read_to_string(root.join("SPDG/dir.list")).expect("dir.list");
    let lines: Vec<&str> = listing.split_terminator("\r\n").collect();
    assert_eq!(lines.len(), 1, "{listing:?}");
    let (size, name) = lines[0].split_once(' ').expect("<size> <name>");
    assert!(
        name.starts_with("SPDG_2026") && name.ends_with(".ar2v"),
        "{name}"
    );
    let published = root.join("SPDG").join(name);
    assert_eq!(
        size.parse::<u64>().ok(),
        fs::metadata(&published).ok().map(|m| m.len())
    );
    let report = json(&run([
        OsStr::new("info"),
        OsStr::new("--json"),
        published.as_os_str(),
    ]));
    assert_eq!(report["volumes"][0]["site"], "SPDG");
    fs::remove_dir_all(&dir).expect("clean up");
}

/// Every file under `dir`, at any depth.
fn walk(dir: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for entry in fs::read_dir(dir).expect("read dir").flatten() {
        let path = entry.path();
        if path.is_dir() {
            files.extend(walk(&path));
        } else {
            files.push(path);
        }
    }
    files
}

fn http_get(address: &str, path: &str) -> (String, Vec<u8>) {
    let mut stream = TcpStream::connect(address).expect("connect");
    write!(stream, "GET {path} HTTP/1.1\r\nHost: {address}\r\n\r\n").expect("send request");
    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("read response");
    let split = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .expect("header end");
    let head = String::from_utf8_lossy(&response[..split]).into_owned();
    (head, response[split + 4..].to_vec())
}

#[test]
fn serve_answers_like_a_polling_server() {
    let dir = scratch("serve");
    let listing = fixture("polling-ndswc-kxwa-dir-list-20260925");
    fs::create_dir_all(dir.join("KXWA")).expect("site folder");
    fs::copy(&listing, dir.join("KXWA/dir.list")).expect("copy listing");

    let mut child = Command::new(env!("CARGO_BIN_EXE_recast-radar"))
        .args([
            OsStr::new("serve"),
            dir.as_os_str(),
            OsStr::new("--bind"),
            OsStr::new("127.0.0.1:0"),
            OsStr::new("--max-requests"),
            OsStr::new("3"),
        ])
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .expect("start server");
    let mut line = String::new();
    BufReader::new(child.stdout.take().expect("stdout"))
        .read_line(&mut line)
        .expect("server banner");
    let address = line
        .split("http://")
        .nth(1)
        .and_then(|rest| rest.split('/').next())
        .expect("address in banner")
        .to_owned();

    let (head, body) = http_get(&address, "/KXWA/dir.list");
    assert!(head.starts_with("HTTP/1.1 200"), "{head}");
    assert_eq!(body, fs::read(&listing).expect("read listing"));
    let (head, body) = http_get(&address, "/");
    assert!(head.starts_with("HTTP/1.1 200"), "{head}");
    assert!(String::from_utf8_lossy(&body).contains("KXWA/"));
    let (head, _) = http_get(&address, "/../Cargo.toml");
    assert!(
        head.starts_with("HTTP/1.1 403") || head.starts_with("HTTP/1.1 404"),
        "{head}"
    );

    let status = child.wait().expect("server exits after 3 requests");
    assert!(status.success());
    fs::remove_dir_all(&dir).expect("clean up");
}

#[cfg(feature = "net")]
#[test]
fn fetch_lists_providers_and_sites_offline() {
    let output = run(["fetch", "intl"]);
    assert!(output.status.success(), "{}", stderr(&output));
    let text = stdout(&output);
    for provider in ["smhi", "dwd", "fmi", "jma"] {
        assert!(text.contains(provider), "{provider}: {text}");
    }
    let output = run(["fetch", "intl", "smhi", "--list-sites"]);
    assert!(output.status.success(), "{}", stderr(&output));
    assert!(!stdout(&output).trim().is_empty());

    let sites = json(&run(["fetch", "sites", "--json"]));
    let ktlx = sites
        .as_array()
        .expect("sites")
        .iter()
        .find(|site| site["id"] == "KTLX")
        .expect("KTLX in the embedded table");
    assert!((ktlx["latitude_deg"].as_f64().unwrap_or(0.0) - 35.33).abs() < 0.05);

    let output = run(["fetch", "intl", "nope"]);
    assert_eq!(output.status.code(), Some(2));

    // --date needs a provider with an archive; the refusal names them, and
    // comes before any request.
    let output = run(["fetch", "intl", "dmi", "dkste", "--date", "2026-06-12"]);
    assert_eq!(output.status.code(), Some(2), "{}", stderr(&output));
    assert!(
        stderr(&output).contains("has no archive"),
        "{}",
        stderr(&output)
    );
    assert!(stderr(&output).contains("smhi"), "{}", stderr(&output));
    let output = run(["fetch", "intl", "smhi", "--time", "12:00", "hemse"]);
    assert_eq!(output.status.code(), Some(2), "{}", stderr(&output));
}

#[cfg(not(feature = "net"))]
#[test]
fn fetch_needs_the_net_feature() {
    let output = run(["fetch", "sites"]);
    assert_eq!(output.status.code(), Some(3), "{}", stderr(&output));
    assert!(stderr(&output).contains("net"), "{}", stderr(&output));
}
